"""Glossary terms: metrics, SLOs and web performance. See build.py for the fields."""

TERMS = [
    dict(slug='throughput', name='Throughput', cat='metrics',
         definition='Throughput is the amount of work a system completes per unit of time, such as requests per second, orders per minute or messages per second.',
         why='Throughput is the other half of every performance result. A fast response time means little if the system only managed 20 requests a second. When throughput stops rising as load increases, you have found a limit.',
         example='Load rises from 100 to 400 requests a second and throughput follows it. From 400 to 500 offered, throughput stays at 410 while response times climb from 200 ms to 2 s. The system is saturated at about 410 requests a second, and the extra load only builds a queue.',
         measure='Count completed requests per second on the server or load balancer, not just what the load tool sent. Plot throughput against offered load: the point where the line goes flat is the capacity limit.',
         mistakes=['Counting failed requests as throughput.',
                   'Measuring only at the load tool, which can disagree with the server when connections are dropped.'],
         related=['tps-and-rps', 'littles-law', 'saturation', 'latency-vs-response-time']),

    dict(slug='tps-and-rps', name='TPS and RPS', cat='metrics', h1='What are TPS and RPS?', aka=['transactions per second', 'requests per second'],
         definition='TPS (transactions per second) and RPS (requests per second) are rates of throughput, where a request is one HTTP call and a transaction is a business action that may need several requests.',
         why='Mixing them up causes badly sized tests. "500 TPS" from the business usually means 500 business actions, which may be 3,000 HTTP requests a second on the server once you count the API calls, images and redirects behind each one.',
         example='A checkout transaction makes 6 API calls. The business forecasts 50 checkouts a second at peak, which is 50 TPS. The APIs see 300 RPS from checkout alone, before browsing and search are added.',
         measure='Agree in writing what a transaction is, count the requests behind each one from a recorded session, and size the test in both units. In k6, iterations a second is roughly transactions a second.',
         mistakes=['Quoting TPS with no definition of a transaction.',
                   'Planning server capacity from TPS without multiplying by requests per transaction.'],
         related=['throughput', 'arrival-rate', 'workload-model', 'littles-law']),

    dict(slug='latency-vs-response-time', name='Latency vs response time', cat='metrics',
         h1='What is the difference between latency and response time?',
         definition='Response time is the full time a user waits for a request, from sending it to receiving the full answer, while latency usually means the delay before the response starts, such as network travel or time spent waiting in a queue.',
         why='People use the words loosely, so teams compare different things. A service can report 20 ms "latency" for its own processing while users see 900 ms, because of queueing, network hops, TLS handshakes and downloading the response.',
         example='A request from Perth to a Sydney data centre spends about 50 ms on the network round trip, waits 300 ms in a queue under load, takes 80 ms to process and 70 ms to download. Response time is 500 ms. The service\'s own metric shows only the 80 ms.',
         measure='Define each metric when you report it. In k6, http_req_duration is the time from sending to receiving the whole response, and http_req_waiting is time to first byte. Measure on the client side for user experience.',
         mistakes=['Comparing server-side timings with client-side timings as if they were the same.',
                   'Leaving queueing time out of a service\'s reported latency.'],
         related=['ttfb', 'percentiles', 'tail-latency', 'utilisation-law']),

    dict(slug='percentiles', name='Percentiles (p95, p99)', cat='metrics', h1='What are percentiles like p95 and p99?', aka=['p95', 'p99', 'p50', 'median'],
         definition='A percentile is the value below which a given share of measurements fall, so p95 is the response time that 95% of requests were faster than and 5% were slower than.',
         why='Averages hide pain. A page with an average of 300 ms can have 1 in 20 requests taking 3 s. Percentiles describe what most users get (p50), what unlucky users get (p95) and what the worst-served users get (p99).',
         example='Out of 10,000 requests, 9,500 finish under 400 ms and 9,900 finish under 2.1 s. p95 is 400 ms and p99 is 2.1 s. If each page view makes 20 requests, most page views include at least one request slower than p95, so the tail is not rare for users.',
         measure='Calculate percentiles from raw measurements or a histogram over a clear time window. Never average percentiles from different servers or time periods, because the result is not a real percentile.',
         mistakes=['Averaging p95 values across servers.',
                   'Reporting p99 from a small sample, such as 200 requests, where it rests on 2 data points.'],
         related=['tail-latency', 'fan-out-amplification', 'thresholds', 'slo', 'coordinated-omission'],
         links=[('/tools/k6-results/', 'k6 results explainer')]),

    dict(slug='tail-latency', name='Tail latency', cat='metrics',
         definition='Tail latency is the response time of the slowest requests, usually measured at p99, p99.9 or the maximum, which is often far slower than the median.',
         why='Tails get worse under load first, and they spread. In a system made of many services, one service\'s slow tail becomes a common delay for whole pages, so tail latency often sets the user experience at scale.',
         example='A service has p50 of 40 ms and p99 of 900 ms. The gap comes from a garbage collection pause every few seconds and a lock on a shared cache. Users rarely see the median, because each page calls this service 15 times.',
         measure='Record high-resolution histograms, look at p99 and p99.9 as well as p95, and line up spikes with garbage collection logs, queue depth and retries. Make sure the load tool is not hiding the tail through coordinated omission.',
         mistakes=['Dismissing p99 as outliers.',
                   'Measuring with a closed model that slows down during stalls and under-reports the tail.'],
         related=['percentiles', 'fan-out-amplification', 'coordinated-omission', 'garbage-collection-pause']),

    dict(slug='fan-out-amplification', name='Fan-out amplification', cat='metrics', aka=['long tail', 'tail at scale'],
         definition='Fan-out amplification is the effect where a request that calls many backend services in parallel is only as fast as the slowest of them, so rare slow responses become common for the overall request.',
         why='It is why p99 matters even when 99% sounds good. The more services or shards each request touches, the more likely at least one of them is having a slow moment.',
         example='Each backend call has a 1% chance of being slower than 1 s. A page that waits on 1 call is slow 1% of the time. A page that fans out to 100 calls is slow 1 − 0.99¹⁰⁰ ≈ 63% of the time. The rare tail is now the normal experience.',
         measure='Count how many calls each user-facing request makes, measure each dependency\'s tail, and trace slow requests to see which call held them up. Fixes include fewer calls, timeouts with fallbacks, and hedged requests (sending a second copy if the first is slow).',
         mistakes=['Setting per-service targets at p95 when each page waits on dozens of services.',
                   'Adding hedged requests without a limit, which adds load exactly when the system is slow.'],
         related=['tail-latency', 'percentiles', 'distributed-tracing', 'retry-storm']),

    dict(slug='apdex', name='Apdex', cat='metrics', aka=['Application Performance Index'],
         definition='Apdex is a score from 0 to 1 that rates user satisfaction with response times, counting requests as satisfied (at or under a target T), tolerating (up to 4T) or frustrated (over 4T).',
         why='It turns a distribution into one number that non-engineers can follow over time. Many APM tools show it by default, so you will meet it in dashboards and reports.',
         example='With T = 500 ms, out of 1,000 requests 850 take 500 ms or less, 100 take up to 2 s and 50 take longer. Apdex = (850 + 100 ÷ 2) ÷ 1,000 = 0.90.',
         measure='Pick T per transaction to match what users expect (a search and a report export deserve different targets), then compute satisfied plus half of tolerating, divided by the total. Errors are usually counted as frustrated.',
         mistakes=['Using one T for every transaction.',
                   'Treating 0.90 as good without looking at what the frustrated 5% are doing, which is often checkout.'],
         related=['percentiles', 'sli', 'apm', 'slo']),

    dict(slug='sli', name='SLI (service level indicator)', cat='metrics', aka=['service level indicator'],
         definition='An SLI is a measured number that shows how well a service is doing for its users, usually a ratio of good events to total events, such as the share of requests served successfully in under 300 ms.',
         why='You can\'t set a sensible target, or know whether you are meeting one, without a precise measure. A good SLI reflects what users feel, not what is easy to collect, such as CPU.',
         example='The SLI for search is: requests that return status 200 in under 400 ms, measured at the load balancer, divided by all search requests. Yesterday it was 99,412 good out of 100,000, which is 99.41%.',
         measure='Pick events users care about, define good and total exactly (where it is measured, which status codes count, the latency limit), and collect them from load balancer or service logs.',
         mistakes=['Using server CPU or uptime pings as an SLI.',
                   'Measuring only successful requests\' latency and ignoring the failures.'],
         related=['slo', 'sla', 'error-budget', 'red-method']),

    dict(slug='slo', name='SLO (service level objective)', cat='metrics', aka=['service level objective'],
         definition='An SLO is a target for an SLI over a time window, such as "99.9% of checkout requests succeed in under 800 ms over 30 days", that a team agrees to meet.',
         why='An SLO says how reliable is reliable enough. It gives teams a clear line for when to slow down feature work and fix reliability, and it gives load tests real pass marks instead of guesses.',
         example='A 99.9% success SLO over 30 days on 10 million requests allows 10,000 failed or slow requests. A load test for the next release uses the same definition as its threshold, so test results and production targets match.',
         measure='Track the SLI continuously, compare it with the target over a rolling window and alert on how fast the error budget is being used, not on every small blip.',
         mistakes=['Setting 99.99% because it sounds good, when users and the business would accept 99.5%.',
                   'Having SLOs that nobody uses to make decisions.'],
         related=['sli', 'error-budget', 'burn-rate', 'sla', 'thresholds'],
         links=[('/tools/slo-calculator/', 'SLO and error budget calculator')]),

    dict(slug='sla', name='SLA (service level agreement)', cat='metrics', aka=['service level agreement'],
         definition='An SLA is a contract with customers that promises a level of service, such as 99.9% monthly availability, and sets out what happens, usually service credits or refunds, if it is missed.',
         why='An SLA is a business and legal promise, so it should be looser than the internal SLO. If you aim exactly at your SLA, you will breach it on the first bad month.',
         example='A provider promises 99.9% monthly availability with a 10% credit below that. Internally it runs to an SLO of 99.95%, so the team gets an early warning and time to react long before customers are owed money.',
         measure='Measure against the exact definitions in the contract (what counts as downtime, which regions, excluded maintenance), which are often different from the engineering SLI.',
         mistakes=['Using SLA and SLO as if they mean the same thing.',
                   'Promising an SLA the dependencies can\'t support, such as 99.99% on top of a database that offers 99.95%.'],
         related=['slo', 'sli', 'error-budget']),

    dict(slug='error-budget', name='Error budget', cat='metrics',
         definition='An error budget is the amount of unreliability an SLO allows over its window, equal to 100% minus the SLO target, such as 0.1% of requests or about 43 minutes a month for 99.9%.',
         why='It turns reliability into something you can spend. While budget remains, the team can ship and take risks. When it is used up, the agreed response is to slow releases and fix reliability, which settles arguments with data.',
         example='99.9% over 30 days is 43.2 minutes of full downtime, or 0.1% of requests. A bad deploy causes 15 minutes of errors on 40% of traffic, which uses about 6 minutes of budget equivalent, roughly 14% of the month\'s allowance.',
         measure='Calculate the allowed bad events or minutes from the SLO, then track how much has been used in the current window. Most monitoring tools can graph budget remaining.',
         mistakes=['Calculating the budget once and never tracking it.',
                   'Having no agreed action when the budget runs out.'],
         related=['slo', 'burn-rate', 'sli', 'sla'],
         links=[('/tools/slo-calculator/', 'SLO and error budget calculator')]),

    dict(slug='burn-rate', name='Burn rate', cat='metrics',
         definition='Burn rate is how fast a service is using its error budget compared with the steady rate that would use it up exactly at the end of the SLO window, so a burn rate of 1 is on track and 10 is ten times too fast.',
         why='Alerting on burn rate catches serious problems quickly without paging people for small blips. It is the standard way to alert on SLOs, described in Google\'s Site Reliability Workbook.',
         example='With a 99.9% SLO, an error rate of 1.44% is a burn rate of 14.4. Kept up for one hour, it uses 2% of a 30 day budget. That is a common trigger for an urgent page, while a burn rate of 1 to 2 might only open a ticket.',
         measure='Burn rate = observed error rate ÷ (1 − SLO). Alert when both a long window (such as 1 hour) and a short window (such as 5 minutes) are over the limit, so alerts fire fast and clear fast.',
         mistakes=['Alerting on raw error rate with a fixed number that ignores the SLO.',
                   'Using one window only, which either fires too slowly or flaps.'],
         related=['error-budget', 'slo', 'sli', 'error-rate'],
         links=[('/tools/slo-calculator/', 'Burn-rate alert calculator')]),

    dict(slug='littles-law', name="Little's Law", cat='metrics',
         definition="Little's Law says that the average number of items in a stable system equals their average arrival rate multiplied by the average time each one spends in the system, written L = λ × W.",
         why='It is the most useful single formula in capacity planning. It sizes virtual users, thread pools and connection pools, and it checks whether test results are believable.',
         example='An API handles 200 requests a second with an average response time of 0.25 s. On average 200 × 0.25 = 50 requests are in flight. A load test of 50 requests a second with users who each spend 0.8 s waiting plus 5 s thinking needs 50 × 5.8 = 290 virtual users.',
         measure='Use averages from a steady-state window. If the numbers from your test don\'t satisfy the law (for example, users × iterations per user doesn\'t match measured throughput), something in the test or the measurement is wrong.',
         mistakes=['Applying it during ramp-up, when the system is not stable.',
                   'Using p95 response time in place of the average.'],
         related=['virtual-user', 'thread-pool', 'connection-pool', 'throughput', 'utilisation-law'],
         links=[('/tools/#virtual-users', "Little's Law virtual users calculator"), ('/tools/capacity-calculator/', 'Capacity calculator')]),

    dict(slug='coordinated-omission', name='Coordinated omission', cat='metrics',
         definition='Coordinated omission is a measurement error where a load tool waits for slow responses before sending the next request, so it sends fewer requests during a stall and under-reports how slow the system really was.',
         why='The name comes from Gil Tene. It means many load tests report p99 values that look fine while real users, who keep arriving during the stall, wait much longer. It hides exactly the problems you are testing for.',
         example='A tool sends one request every 10 ms. The server freezes for 2 s. The tool records one 2 s response and then carries on. Real users arriving every 10 ms would have produced about 200 slow responses, averaging around 1 s each. The reported p99 is far too low.',
         measure='Use an open model (arrival-rate executors in k6) so requests keep arriving on schedule, or tools that correct for it, such as wrk2 and HdrHistogram. Watch for dropped iterations, which show the tool fell behind.',
         mistakes=['Trusting p99 from a closed-model test of a public-facing system.',
                   'Giving the test too few virtual users, so an arrival-rate test can\'t keep to its schedule either.'],
         related=['open-vs-closed-workload-model', 'tail-latency', 'percentiles', 'arrival-rate'],
         links=[('/tools/#coordinated-omission', 'Coordinated omission simulator'), ('/blog/coordinated-omission-why-your-load-tool-under-reports-tail-latency/', 'Deep dive: coordinated omission')]),

    dict(slug='ttfb', name='TTFB (time to first byte)', cat='metrics', aka=['time to first byte'],
         definition='TTFB is the time from a browser or client starting a request until the first byte of the response arrives, covering redirects, DNS, connection set-up, TLS and the server\'s time to start replying.',
         why='Nothing on the page can render until the first byte arrives, so a slow TTFB delays everything after it, including LCP. Under load, rising TTFB is often the first sign the server is queueing.',
         example='The home page has a TTFB of 1.6 s on mobile. Of that, 400 ms is a redirect from http to https and then to www, and 1 s is the server building the page. Removing the redirect chain and caching the page at the CDN brings TTFB to 250 ms.',
         measure='Use browser dev tools, Lighthouse or real-user data for pages. web.dev suggests a TTFB of 0.8 s or less at the 75th percentile as a rough guide. In k6, http_req_waiting is the server part of it.',
         mistakes=['Treating TTFB as a pure server metric when redirects and network set-up are part of it.',
                   'Measuring TTFB only from a fast office connection.'],
         related=['lcp', 'latency-vs-response-time', 'core-web-vitals', 'cdn-hit-ratio']),

    dict(slug='lcp', name='LCP (Largest Contentful Paint)', cat='metrics', aka=['Largest Contentful Paint'],
         definition='LCP is a Core Web Vital that measures how long it takes for the largest image or block of text in the viewport to appear, with 2.5 seconds or less at the 75th percentile counted as good.',
         why='LCP is the closest single number to "when did the page look loaded". It feeds Google\'s page experience signals, and slow LCP on product and landing pages costs conversions.',
         example='A product page\'s hero image is 1.8 MB, lazy-loaded and discovered late because it is set in CSS. LCP is 4.6 s on mobile. Serving a 180 KB modern-format image, marking it high priority and not lazy-loading it brings LCP to 2.1 s.',
         measure='Field data (Chrome UX Report, real-user monitoring) shows what visitors actually get. Lighthouse and WebPageTest give lab data for debugging. Above 4 s is rated poor.',
         mistakes=['Lazy-loading the hero image.',
                   'Checking LCP on a fast laptop when most visitors are on mid-range phones.'],
         related=['core-web-vitals', 'ttfb', 'inp', 'cls', 'performance-budget']),

    dict(slug='inp', name='INP (Interaction to Next Paint)', cat='metrics', aka=['Interaction to Next Paint'],
         definition='INP is a Core Web Vital that measures how quickly a page responds visually to clicks, taps and key presses across the whole visit, with 200 milliseconds or less at the 75th percentile counted as good.',
         why='INP replaced First Input Delay (FID) as a Core Web Vital in March 2024. FID only measured the delay before the first interaction was handled. INP looks at almost every interaction, so slow JavaScript later in the visit now counts.',
         example='Tapping "Add to cart" runs 450 ms of JavaScript for analytics, a recommendations update and a re-render before the button changes. INP is about 500 ms, rated poor. Updating the button first and deferring the rest brings it under 200 ms.',
         measure='Field data from the Chrome UX Report or real-user monitoring is the reliable source, because lab tools don\'t interact like people. In the lab, use the Performance panel in Chrome dev tools to find long tasks. Over 500 ms is rated poor.',
         mistakes=['Optimising only page load when the problem is JavaScript that runs on each click.',
                   'Still reporting FID, which is no longer a Core Web Vital.'],
         related=['core-web-vitals', 'lcp', 'cls', 'real-user-monitoring']),

    dict(slug='cls', name='CLS (Cumulative Layout Shift)', cat='metrics', aka=['Cumulative Layout Shift'],
         definition='CLS is a Core Web Vital that measures how much visible content unexpectedly moves while a page is in use, with a score of 0.1 or less at the 75th percentile counted as good.',
         why='Layout shifts make people tap the wrong thing, lose their place while reading and distrust the page. A banner that pushes the "Buy" button down just as someone taps it is a real cost.',
         example='A cookie banner and a late-loading promotion strip push the page down by 120 pixels after it first appears. CLS is 0.31, which is poor (over 0.25). Reserving space for both and setting width and height on images brings it to 0.04.',
         measure='Use field data from the Chrome UX Report or real-user monitoring, and Lighthouse or the Chrome dev tools Performance panel to find which elements shift. Shifts within 500 ms of a user\'s input don\'t count.',
         mistakes=['Images and ads without reserved space.',
                   'Web fonts that swap in with very different sizes.'],
         related=['core-web-vitals', 'lcp', 'inp', 'performance-budget']),

    dict(slug='core-web-vitals', name='Core Web Vitals', cat='metrics',
         definition='Core Web Vitals are Google\'s three key measures of real-world page experience: LCP for loading, INP for responsiveness and CLS for visual stability, each judged at the 75th percentile of visits.',
         why='They are the shared language for front-end performance, they feed Google\'s page experience signals used in search, and they track what real visitors experience on real devices.',
         example='A page passes when at least 75% of visits get LCP of 2.5 s or less, INP of 200 ms or less and CLS of 0.1 or less, measured separately for mobile and desktop. A page with good LCP and CLS but INP of 320 ms fails the assessment.',
         measure='Check field data in PageSpeed Insights or Search Console (from the Chrome UX Report), and use real-user monitoring for your own traffic. Use Lighthouse for lab debugging.',
         mistakes=['Chasing a Lighthouse score of 100 instead of fixing field data.',
                   'Ignoring that INP replaced FID in March 2024.'],
         related=['lcp', 'inp', 'cls', 'ttfb', 'real-user-monitoring']),

    dict(slug='error-rate', name='Error rate', cat='metrics',
         definition='Error rate is the share of requests or transactions that fail, such as returning an HTTP 5xx status, timing out or returning the wrong content, out of all requests in a time window.',
         why='Response times only describe the requests that worked. A system under too much load often fails fast, so a falling response time with a rising error rate is a warning, not an improvement.',
         example='At 300 requests a second, errors are 0.05%. At 450, the error rate jumps to 6% as the database pool times out, while p95 for successful requests barely moves. The headline latency hides that 1 in 17 customers got an error.',
         measure='Count failures by type (5xx, 4xx that shouldn\'t happen, timeouts, failed checks) and divide by the total. In k6, the http_req_failed metric and check results give both views.',
         code="""thresholds: { http_req_failed: ['rate<0.01'], checks: ['rate>0.99'] }""",
         mistakes=['Counting only 5xx and missing timeouts or wrong content with a 200 status.',
                   'Reporting latency without the error rate next to it.'],
         related=['checks-and-assertions', 'sli', 'burn-rate', 'red-method']),
]
